 if('IntersectionObserver' in window){const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');observer.unobserve(entry.target);}}),{threshold:.08});$$('.reveal').forEach(el=>observer.observe(el));}else $$('.reveal').forEach(el=>el.classList.add('visible'));
 let frame=false;function progress(){if(frame)return;frame=true;requestAnimationFrame(()=>{const total=document.documentElement.scrollHeight-innerHeight;$('.reading-progress').style.width=(total>0?scrollY/total*100:0)+'%';if(scrollY>90)mega.classList.remove('open');frame=false;});}addEventListener('scroll',progress,{passive:true});progress();
